import Link from "next/link"
import { biLocale } from "@/lib/dashboard/bi-presentation"
import { ArrowUpRight, CalendarClock, LockKeyhole, ShieldAlert } from "lucide-react"

import { BIEvidenceBadgeRow } from "@/components/bi/BIEvidenceBadgeRow"
import { BISeverityBadge, BIStateBadge } from "@/components/bi/BIStateBadge"
import { BIStateSurface } from "@/components/bi/BIStateSurface"
import { Button } from "@/components/ui/button"
import {
  dashboardMutedTextClass,
  dashboardPanelClass,
  dashboardRowClass,
  dashboardToneClass,
} from "@/components/finance/finance-dashboard-theme"
import { cn } from "@/lib/utils"
import type {
  BIActionLink,
  BIBlocker,
  BIFreshness,
  BIKpiState,
  BIRedaction,
  BISeverity,
  BITrustState,
} from "@/services/bi/bi-contracts"
import type { EvidenceGrade } from "@/services/evidence/evidence-contracts"

export type BIActionPriorityItem = {
  id: string
  title: string
  nextStep: string
  severity: BISeverity
  state: BIKpiState
  actionLink: BIActionLink
  evidenceGrade?: EvidenceGrade
  trustState?: BITrustState
  freshness?: BIFreshness
  dueLabel?: string | null
  ownerLabel?: string | null
  blockers?: BIBlocker[]
  redactions?: BIRedaction[]
}

type BIActionPriorityBoardProps = {
  items: BIActionPriorityItem[]
  locale?: string
  title?: string
  detail?: string
  className?: string
  maxItems?: number
  emptyTitle?: string
  emptyDetail?: string
}

export function BIActionPriorityBoard({
  items,
  title,
  detail,
  locale = "en",
  className,
  maxItems = 8,
  emptyTitle,
  emptyDetail,
}: BIActionPriorityBoardProps) {
  const visible = items.slice(0, maxItems)
  const french = biLocale(locale) === "fr"

  return (
    <section className={cn(dashboardPanelClass, "p-4", className)}>
      <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h2 className="text-base font-semibold text-[var(--dash-text)]">{title ?? (french ? "Actions à traiter aujourd’hui" : "What needs action today")}</h2>
          <p className={cn("text-sm", dashboardMutedTextClass)}>{detail ?? (french ? "Actions accessibles selon vos droits, classées par urgence, risque et impact métier." : "Permission-filtered actions ranked by urgency, risk, and business impact.")}</p>
        </div>
        <span className="rounded-md border border-[var(--dash-border-subtle)] px-2 py-1 text-xs text-[var(--dash-text-soft)]">
          {items.length} action{items.length === 1 ? "" : "s"}
        </span>
      </div>

      {visible.length ? (
        <div className="mt-4 space-y-3">
          {visible.map((item) => (
            <article key={item.id} className={cn(dashboardRowClass, "p-3")}>
              <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <BISeverityBadge severity={item.severity} locale={locale} />
                    <BIStateBadge state={item.state} locale={locale} />
                    {item.dueLabel ? (
                      <span className="inline-flex items-center gap-1.5 rounded-md border border-[var(--dash-border-subtle)] px-2 py-1 text-xs text-[var(--dash-text-soft)]">
                        <CalendarClock className="h-3.5 w-3.5" aria-hidden="true" />
                        {item.dueLabel}
                      </span>
                    ) : null}
                  </div>
                  <h3 className="mt-3 text-sm font-semibold text-[var(--dash-text)]">{item.title}</h3>
                  <p className={cn("mt-1 text-sm leading-6", dashboardMutedTextClass)}>{item.nextStep}</p>
                </div>
                <ActionButton action={item.actionLink} />
              </div>

              {item.evidenceGrade && item.trustState && item.freshness ? (
                <BIEvidenceBadgeRow
                  locale={locale}
                  className="mt-3"
                  evidenceGrade={item.evidenceGrade}
                  trustState={item.trustState}
                  freshness={item.freshness}
                />
              ) : null}

              {item.ownerLabel || item.blockers?.length || item.redactions?.length ? (
                <div className="mt-3 flex flex-wrap gap-2 text-xs">
                  {item.ownerLabel ? (
                    <span className="rounded-md border border-[var(--dash-border-subtle)] px-2 py-1 text-[var(--dash-text-soft)]">
                      {item.ownerLabel}
                    </span>
                  ) : null}
                  {item.blockers?.map((blocker) => (
                    <span key={blocker.id} className={cn("rounded-md border px-2 py-1", dashboardToneClass("danger"))}>
                      {blocker.title}
                    </span>
                  ))}
                  {item.redactions?.map((redaction) => (
                    <span key={redaction.id} className={cn("rounded-md border px-2 py-1", dashboardToneClass("gold"))}>
                      {redaction.field}
                    </span>
                  ))}
                </div>
              ) : null}
            </article>
          ))}
        </div>
      ) : (
        <BIStateSurface
          state="empty"
          title={emptyTitle ?? (french ? "Aucune action visible à traiter" : "No visible action is due")}
          detail={emptyDetail ?? (french ? "Aucune action accessible selon vos droits n’est actuellement affichée pour cette organisation." : "There is no permission-filtered command action for this user and tenant right now.")}
          className="mt-4"
        />
      )}
    </section>
  )
}

function ActionButton({ action }: { action: BIActionLink }) {
  if (action.disabled) {
    return (
      <Button
        size="sm"
        variant="outline"
        disabled
        title={action.disabledReason ?? undefined}
        className="shrink-0 rounded-lg border-[var(--dash-border-subtle)] text-[var(--dash-text-soft)]"
      >
        <ShieldAlert className="h-4 w-4" aria-hidden="true" />
        {action.label}
      </Button>
    )
  }

  if (!action.href) {
    return (
      <Button
        size="sm"
        variant="outline"
        disabled
        className="shrink-0 rounded-lg border-[var(--dash-border-subtle)] text-[var(--dash-text-soft)]"
      >
        <LockKeyhole className="h-4 w-4" aria-hidden="true" />
        {action.label}
      </Button>
    )
  }

  return (
    <Button asChild size="sm" variant="outline" className="shrink-0 rounded-lg border-[var(--dash-border-subtle)] text-[var(--dash-text)]">
      <Link href={action.href}>
        <ArrowUpRight className="h-4 w-4" aria-hidden="true" />
        {action.label}
      </Link>
    </Button>
  )
}

components/bi/BIRiskOpportunityRadar.tsx:
import { biLocale, biCopy } from "@/lib/dashboard/bi-presentation"
import Link from "next/link"
import { ArrowUpRight, Banknote, EyeOff, ShieldAlert, TimerReset } from "lucide-react"

import { BIEvidenceBadgeRow } from "@/components/bi/BIEvidenceBadgeRow"
import { BISeverityBadge, BIStateBadge } from "@/components/bi/BIStateBadge"
import { BIStateSurface } from "@/components/bi/BIStateSurface"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import {
  dashboardMutedTextClass,
  dashboardPanelClass,
  dashboardRowClass,
  dashboardToneClass,
} from "@/components/finance/finance-dashboard-theme"
import { cn } from "@/lib/utils"
import type { BIActionLink, BIRiskRank, BIUnassessedObservation } from "@/services/bi/bi-contracts"

type BIRiskOpportunityRadarProps = {
  risks: (BIRiskRank | BIUnassessedObservation)[]
  title?: string
  detail?: string
  locale?: string
  currencyCode?: string
  className?: string
  maxItems?: number
}

export function BIRiskOpportunityRadar({
  risks,
  title,
  detail,
  locale = "en",
  currencyCode = "XAF",
  className,
  maxItems = 6,
}: BIRiskOpportunityRadarProps) {
  const visible = [...risks].sort((left, right) => left.rank - right.rank).slice(0, maxItems)

  return (
    <section className={cn(dashboardPanelClass, "min-w-0 p-4", className)}>
      <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
        <div>
          <h2 className="text-base font-semibold text-[var(--dash-text)]">{title ?? biCopy[biLocale(locale)].radar}</h2>
          <p className={cn("text-sm", dashboardMutedTextClass)}>{detail ?? biCopy[biLocale(locale)].radarDetail}</p>
        </div>
        <Badge variant="outline" className="w-fit rounded-md border-[var(--dash-border-subtle)] text-[var(--dash-text-soft)]">
          {risks.length} {locale.startsWith("fr") ? risks.length === 1 ? "signal" : "signaux" : risks.length === 1 ? "signal" : "signals"}
        </Badge>
      </div>

      {visible.length ? (
        <div className="mt-4 space-y-3">
          {visible.map((risk) => (
            <article key={risk.id} className={cn(dashboardRowClass, "p-3")}>
              <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <Badge variant="outline" className={cn("border", dashboardToneClass(risk.severity === "high" || risk.severity === "critical" ? "danger" : risk.severity === "medium" ? "gold" : "info"))}>
                      #{risk.rank}
                    </Badge>
                    <BISeverityBadge severity={risk.severity} locale={locale} />
                    <BIStateBadge state={risk.state} locale={locale} />
                    <span className="inline-flex items-center gap-1.5 rounded-md border border-[var(--dash-border-subtle)] px-2 py-1 text-xs text-[var(--dash-text-soft)]">
                      <TimerReset className="h-3.5 w-3.5" aria-hidden="true" />
                      {(risk.urgency === "watch" ? locale.startsWith("fr") ? "à surveiller" : "watch" : risk.urgency === "now" || risk.urgency === "today" || risk.urgency === "soon" ? biCopy[biLocale(locale)][risk.urgency] : risk.urgency) ?? (locale.startsWith("fr") ? "Urgence non évaluée" : "Urgency not assessed")}
                    </span>
                  </div>
                  <h3 className="mt-3 text-sm font-semibold text-[var(--dash-text)]">{risk.title}</h3>
                  <p className={cn("mt-1 text-sm leading-6", dashboardMutedTextClass)}>{risk.detail}</p>
                  {risk.businessImpact && risk.businessImpact !== risk.detail ? <p className={cn("mt-1 text-sm leading-6", dashboardMutedTextClass)}>{risk.businessImpact}</p> : null}
                </div>
                <div className="flex min-w-0 flex-col items-start gap-2 lg:max-w-[50%] lg:items-end">
                  {risk.moneyImpact !== null ? (
                    <span className="inline-flex items-center gap-1.5 rounded-md border border-[var(--dash-border-subtle)] px-2 py-1 text-xs font-medium text-[var(--dash-text)]">
                      <Banknote className="h-3.5 w-3.5" aria-hidden="true" />
                      {formatMoney(risk.moneyImpact, locale, currencyCode)}
                    </span>
                  ) : null}
                  {risk.actionLink ? <RiskActionButton action={risk.actionLink} /> : null}
                </div>
              </div>

              <BIEvidenceBadgeRow locale={locale}
                className="mt-3"
                evidenceGrade={risk.evidenceGrade}
                trustState={risk.trustState}
                freshness={risk.freshness}
              />

              {risk.blockers.length || risk.redactions.length ? (
                <div className="mt-3 flex flex-wrap gap-2 text-xs">
                  {risk.blockers.map((blocker) => (
                    <span key={blocker.id} className={cn("rounded-md border px-2 py-1", dashboardToneClass("danger"))}>
                      <ShieldAlert className="mr-1 inline h-3 w-3" aria-hidden="true" />
                      {blocker.title}
                    </span>
                  ))}
                  {risk.redactions.map((redaction) => (
                    <span key={redaction.id} className={cn("rounded-md border px-2 py-1", dashboardToneClass("gold"))}>
                      <EyeOff className="mr-1 inline h-3 w-3" aria-hidden="true" />
                      {redaction.field}
                    </span>
                  ))}
                </div>
              ) : null}
            </article>
          ))}
        </div>
      ) : (
        <BIStateSurface
          state="empty"
          title={locale.startsWith("fr") ? "Aucun signal affiché" : "No signals displayed"}
          detail={locale.startsWith("fr") ? "L’absence de signal ne prouve pas l’absence de risque. Consultez le périmètre et les limites des sources." : "An empty list does not establish absence of risk. Review the scope and source limitations."}
          className="mt-4"
        />
      )}
    </section>
  )
}

function RiskActionButton({ action }: { action: BIActionLink }) {
  if (action.disabled || !action.href) {
    return (
      <Button
        size="sm"
        variant="outline"
        disabled
        title={action.disabledReason ?? undefined}
        className="h-auto min-h-9 max-w-full whitespace-normal break-words rounded-lg border-[var(--dash-border-subtle)] text-start text-[var(--dash-text-soft)]"
      >
        <ShieldAlert className="h-4 w-4" aria-hidden="true" />
        {action.label}
      </Button>
    )
  }

  return (
    <Button asChild size="sm" variant="outline" className="h-auto min-h-9 max-w-full whitespace-normal break-words rounded-lg border-[var(--dash-border-subtle)] text-start text-[var(--dash-text)]">
      <Link href={action.href}>
        <ArrowUpRight className="h-4 w-4" aria-hidden="true" />
        {action.label}
      </Link>
    </Button>
  )
}

function formatMoney(value: number, locale: string, currencyCode: string) {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency: currencyCode,
  }).format(value)
}

